#!/usr/bin/env node
/**
 * Fast wrapper to check if IPA dictionaries exist before invoking tsx.
 * Avoids tsx startup overhead when dictionaries are already built.
 */

const { existsSync } = require('fs');
const { execSync } = require('child_process');
const { join } = require('path');

const dictsDir = join(__dirname, '..', 'public', 'ipa-dicts');

// Check for at least one foreign dictionary file
const sampleFile = join(dictsDir, 'fr.json');
// Check for English dictionary (generated by build-dictionary.ts)
const enJsonFile = join(dictsDir, 'en.json');

const force = process.argv.includes('--force');

if (!force && existsSync(sampleFile) && existsSync(enJsonFile)) {
  console.log('IPA dictionaries exist, skipping (use --force to rebuild)');
  process.exit(0);
}

// Build foreign dicts if missing
if (force || !existsSync(sampleFile)) {
  execSync('npx tsx --conditions=source scripts/build-ipa-dicts.ts', {
    stdio: 'inherit',
    cwd: join(__dirname, '..'),
  });
}

// Build en.json (from CMU dict + custom words) if missing
if (force || !existsSync(enJsonFile)) {
  execSync('npx tsx --conditions=source scripts/build-dictionary.ts', {
    stdio: 'inherit',
    cwd: join(__dirname, '..', '..', 'dictionary'),
  });
}
